mapper.insert:
 		INSERT INTO VENDOR_IN_CHARGE
 		( VENDOR_CODE
 		, COMPANY_CODE
 		, SEQ
 		, VENDOR_ID
 		, VENDOR_PASSWORD
 		, IN_CHARGE_TYPE
 		, NAME_KOR
 		, NAME_ENG
 		, POSITION
 		, EMAIL
 		, TEL_NO
 		, REMARK
 		, CREATE_DATE
 		, CREATE_BY
 		, UPDATE_DATE
 		, UPDATE_BY
 		, DELETE_YN)
		VALUES 
		( #{vendorCode}
		, #{company_code}
		, ( SELECT COALESCE(MAX(SEQ), 0)
		      FROM VENDOR_IN_CHARGE
		     WHERE COMPANY_CODE = #{company_code}
		       AND VENDOR_CODE = #{vendor_code} )
		, #{vendorCode}
		, #{vendorCode}
		, 'O'
		, #{name_kor}
		, #{name_eng}
		, #{position}
		, #{email}
		, #{tel_no}
		, #{remark}
		, NOW()
		, #{update_by}
		, NOW()
		, #{update_by}
		, 'N')

